-- 0001_init
-- HAND-WRITTEN, as 0002 was: both predate `x db gen` in this app. This line claimed
-- GENERATED by `x db gen "init"` from the initial commit until 2026-08-25, and three things on
-- disk say otherwise — no `0001_init.snapshot.json` was ever written beside it, which the
-- generator emits for every migration it writes; the SQL below is uppercase and unquoted where
-- the generator quotes every identifier; and the statements counted under `ungeneratable:`
-- were ones `x db gen` could not emit when this file was written.
-- Editing an applied migration changes its checksum: X_MIGRATION_CONFLICT on the next apply.
-- reversible: yes  (the `-- down` section below)
-- build: entities@6 invariants@10 indexes@7
-- ungeneratable: 5
--   Five CREATE TYPE … AS ENUM. `x db gen` can only write what an entity declares, so a squash
--   of this directory would discard all five in silence; the count is what makes the drift step
--   carry them instead.
--   It was 7 until 2026-08-26, and the two that left are both ALTER TABLE … REPLICA IDENTITY
--   FULL below: `x db gen` now emits that form from a live query's declared `subscribes:`, and
--   `GENERATABLE_FORMS` (@ultimat3/db) carries the verb phrase, so a squash no longer loses
--   them. `likes` is declassified with `posts` even though no live query subscribes to it —
--   the classifier reads the leading verb phrase and deliberately does not judge a statement's
--   body, so it cannot tell the two apart. See the note beside them.

CREATE TYPE plan_code AS ENUM ('free', 'team', 'business');
CREATE TYPE billing_currency AS ENUM ('USD', 'EUR');
CREATE TYPE member_role AS ENUM ('owner', 'admin', 'author', 'reader');
CREATE TYPE post_status AS ENUM ('draft', 'scheduled', 'published');
CREATE TYPE theme AS ENUM ('system', 'light', 'dark');

CREATE TABLE orgs (
  id                uuid PRIMARY KEY,
  slug              varchar(80) NOT NULL,
  name              varchar(80) NOT NULL,
  plan_code         plan_code NOT NULL DEFAULT 'free',
  billing_currency  billing_currency NOT NULL DEFAULT 'USD',
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT orgs_slug_key UNIQUE (slug),
  CONSTRAINT org_slug_shape CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT org_name_present CHECK (length(btrim(name)) >= 1)
);
CREATE INDEX orgs_plan_code_idx ON orgs (plan_code);

CREATE TABLE members (
  id             uuid PRIMARY KEY,
  org_id         uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
  user_id        uuid NOT NULL,
  email          varchar(254) NOT NULL,
  name           varchar(80) NOT NULL,
  role           member_role NOT NULL DEFAULT 'author',
  tz             text NOT NULL DEFAULT 'UTC',
  locale         text NOT NULL DEFAULT 'en',
  theme          theme NOT NULL DEFAULT 'system',
  digest_opt_in  boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT member_email_shape CHECK (position('@' in email) > 1),
  CONSTRAINT member_unique_per_org UNIQUE (org_id, user_id),
  -- tz() and locale() narrow to the domain's supported sets, so a bad row cannot be written
  -- by a migration, a script, or a psql session either.
  CONSTRAINT member_tz_supported CHECK (tz IN (
    'UTC', 'America/New_York', 'America/Sao_Paulo', 'Europe/Madrid',
    'Europe/Berlin', 'Asia/Tokyo', 'Australia/Sydney', 'Pacific/Auckland')),
  CONSTRAINT member_locale_supported CHECK (locale IN ('en', 'es'))
);
CREATE INDEX members_org_id_role_idx ON members (org_id, role);
CREATE INDEX members_tz_idx ON members (tz) WHERE digest_opt_in;

CREATE TABLE posts (
  id            uuid PRIMARY KEY,
  org_id        uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
  author_id     uuid NOT NULL REFERENCES members (id) ON DELETE RESTRICT,
  slug          varchar(80) NOT NULL,
  title         varchar(120) NOT NULL,
  excerpt       varchar(200) NOT NULL,
  body          text NOT NULL,
  cover_url     text,
  status        post_status NOT NULL DEFAULT 'draft',
  like_count    integer NOT NULL DEFAULT 0,
  published_at  timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT post_slug_shape CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT post_slug_unique_per_org UNIQUE (org_id, slug),
  CONSTRAINT post_like_count_non_negative CHECK (like_count >= 0),
  CONSTRAINT post_publish_coherent CHECK ((status = 'published') = (published_at IS NOT NULL))
);
CREATE INDEX posts_feed_idx ON posts (org_id, published_at DESC) WHERE status = 'published';
CREATE INDEX posts_author_id_idx ON posts (author_id);

CREATE TABLE comments (
  id          uuid PRIMARY KEY,
  org_id      uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
  post_id     uuid NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  author_id   uuid NOT NULL REFERENCES members (id) ON DELETE RESTRICT,
  body        varchar(2000) NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT comment_body_present CHECK (length(btrim(body)) >= 1)
);
CREATE INDEX comments_post_id_created_at_idx ON comments (post_id, created_at);

CREATE TABLE likes (
  org_id      uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
  post_id     uuid NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  member_id   uuid NOT NULL REFERENCES members (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (post_id, member_id)
);
CREATE INDEX likes_member_id_idx ON likes (member_id);

CREATE TABLE plans (
  code              plan_code NOT NULL,
  currency          billing_currency NOT NULL,
  monthly_minor     bigint NOT NULL,
  monthly_currency  char(3) NOT NULL,
  seats             integer NOT NULL,
  PRIMARY KEY (code, currency),
  CONSTRAINT plan_price_non_negative CHECK (monthly_minor >= 0),
  CONSTRAINT plan_currency_matches_price CHECK (monthly_currency = currency::text),
  CONSTRAINT plan_seats_positive CHECK (seats >= 1)
);

-- `posts` is the derived one: `liveFeed` (apps/web/app/posts/live.ts) is this app's only
-- `live: true` query, and it now DECLARES `subscribes: ['posts']`, which is what `x db gen` reads
-- to emit this ALTER and record it on the snapshot. There is no derivable live-query set — the
-- relation lives inside `sql:`, a callback no generator can invoke without valid input — so the
-- declaration is the source, and it is machine-checked against the resolved shape on the first
-- subscribe (X_QUERY_SUBSCRIBES_DRIFT).
-- `likes` is subscribed to by NO live query and is kept BY HAND: this comment claimed both were
-- derived and that was never true of it. Declare a live query on `likes` or delete the line;
-- leaving it is a WAL cost for a table nothing patches.
ALTER TABLE posts REPLICA IDENTITY FULL;
ALTER TABLE likes REPLICA IDENTITY FULL;

-- down

DROP TABLE IF EXISTS plans;
DROP TABLE IF EXISTS likes;
DROP TABLE IF EXISTS comments;
DROP TABLE IF EXISTS posts;
DROP TABLE IF EXISTS members;
DROP TABLE IF EXISTS orgs;

DROP TYPE IF EXISTS theme;
DROP TYPE IF EXISTS post_status;
DROP TYPE IF EXISTS member_role;
DROP TYPE IF EXISTS billing_currency;
DROP TYPE IF EXISTS plan_code;
